using System.Collections.Concurrent;
using System.IO.Compression;
using System.Reflection;
using System.Text;
using Xunit.Sdk;

namespace OcctNative;

/// <summary>
/// Native OCCT, recorded (unit 10A, decision 15001). The oracle tests call native OCCT through <c>N.</c>, which names
/// this namespace: a facade with the members of build123d.NET's native wrappers the tests use (<c>Native.g.cs</c>,
/// generated by <c>tools/oracle-facade.cs</c>). Each call is a step on the running test's tape:
/// <list type="bullet">
/// <item><b>Replaying</b> (the default): the call's results (values, the types of the objects it returns, its exception,
/// the files it wrote) are read from the test's recording, embedded in the assembly (<c>Recordings/*.tape.gz</c>), after
/// checking that it is the call recorded, with the same arguments. No native code runs.</item>
/// <item><b>Recording</b> (<c>OCCTNET_ORACLE_RECORD=1</c>, with native OCCT built in: <c>HAS_ORACLE</c>): the call runs
/// natively (<c>Native.Record.g.cs</c>) and its results are written to the tape, which is saved into the source tree's
/// recordings when the test ends.</item>
/// </list>
/// The port's side always runs. A test therefore compares the port with native's results as recorded, exactly as it
/// compared them live; a port whose results change makes the test ask native different questions, which fails as a
/// call not recorded.
/// </summary>
public static partial class Tape
{
    /// <summary>The environment variable that switches recording on.</summary>
    public const string RecordVariable = "OCCTNET_ORACLE_RECORD";

    private static readonly AsyncLocal<Session?> s_session = new();
    private static readonly ConcurrentDictionary<string, Dictionary<string, byte[]>> s_files = new(StringComparer.Ordinal);
    private static readonly Lock s_saveLock = new();

    /// <summary>Whether this run records native's results (rather than replaying them).</summary>
#if ORACLE_DIRECT
    public static bool IsRecording => false;
#else
    public static bool IsRecording { get; } = Environment.GetEnvironmentVariable(RecordVariable) is "1" or "true";
#endif

    /// <summary>
    /// Whether native OCCT runs in this run: recording, or compiled against it directly (OracleDirect, live as before
    /// unit 10A). Code that only native OCCT can run (build123d.NET's scenarios) runs then; a replay reads its results.
    /// </summary>
#if ORACLE_DIRECT
    public static bool RunsNative => true;
#else
    public static bool RunsNative => IsRecording;
#endif

    /// <summary>The recordings folder in the source tree, which recording writes into.</summary>
    private static string RecordingsDir =>
        typeof(Tape).Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().FirstOrDefault(a => a.Key == "OracleRecordingsDir")?.Value
        ?? throw new InvalidOperationException("The assembly doesn't say where its recordings are (OracleRecordingsDir)");

    /// <summary>The running test's session.</summary>
    internal static Session Current => s_session.Value
                                      ?? throw new InvalidOperationException("A native call outside a test: native OCCT is recorded per test "
                                                                             + "(a static field or a constructor can't call it)");

    /// <summary>Starts a test's tape: its recording file is the test class's, its key the method's.</summary>
    internal static void Begin(MethodInfo theMethod)
    {
        Type aClass = theMethod.ReflectedType ?? theMethod.DeclaringType!;
        s_session.Value = new Session(aClass.Name, theMethod.Name);
    }

    /// <summary>
    /// Names the row of a theory (or another subdivision of a test) whose calls follow: each row has a tape of its own,
    /// so rows can run alone. Ends the previous row's tape.
    /// </summary>
    public static void Row(object theRow)
    {
        Session aSession = Current;
        aSession.Finish();
        s_session.Value = new Session(aSession.File, $"{aSession.BaseKey}[{theRow}]", aSession.BaseKey);
    }

    /// <summary>Ends the test's tape: saved if recording, checked used up if replaying.</summary>
    internal static void End(bool theCheck)
    {
        Session? aSession = s_session.Value;
        s_session.Value = null;
        if (aSession is not null)
        {
            aSession.Finish(theCheck);
        }
    }

    // ---------------------------------------------------------------------------------------------------------------
    // Calls

    /// <summary>
    /// Runs or replays one call: <paramref name="theSelf"/> is the object called (null for a static member or a
    /// constructor), <paramref name="theSignature"/> the member, <paramref name="theArgs"/> its arguments (null for an
    /// out parameter). Returns the results: the return value (if not void), then the out and ref parameters', each as the
    /// facade's own value (a facade object, an enum as a long).
    /// </summary>
    public static object?[] Call(NativeHandle? theSelf, string theSignature, params object?[] theArgs)
        => Current.Call(theSelf, theSignature, theArgs, false).Results;

    /// <summary>A constructor's call: the native object it made (when recording) and its number on the tape.</summary>
    public static Made New(string theSignature, params object?[] theArgs)
    {
        Session aSession = Current;
        (_, object? aReal) = aSession.Call(null, theSignature, theArgs, true);
        return new Made(aSession.NextId(), aReal);
    }

    /// <summary>
    /// A value the test computes from native objects outside the facade (build123d.NET's scenarios, run natively): computed
    /// and recorded when recording, read back when replaying. <paramref name="theWrite"/> and <paramref name="theRead"/>
    /// serialise it; a facade object inside it goes through <see cref="TapeWriter.Object"/>.
    /// </summary>
    public static T Value<T>(string theWhat, Func<T> theCompute, Action<TapeWriter, T> theWrite, Func<TapeReader, T> theRead)
#if ORACLE_DIRECT
        => theCompute(); // live: nothing recorded
#else
        => Current.Value(theWhat, theCompute, theWrite, theRead);
#endif

    /// <summary>A recorded value in one of the tape's own types (string, numbers, arrays of them).</summary>
    public static T Value<T>(string theWhat, Func<T> theCompute)
        => Value(theWhat, theCompute, (w, v) => w.Value(v), r => (T)r.Value()!);

    /// <summary>
    /// Whether this run compares with native OCCT as recorded (replaying or recording), where the largest corpora and
    /// random runs are sampled to keep the recordings small (decision 15002); live (OracleDirect), they run in full.
    /// </summary>
#if ORACLE_DIRECT
    public static bool IsSampled => false;
#else
    public static bool IsSampled => true;
#endif

    /// <summary>A number of random cases: <paramref name="theLive"/> live, <paramref name="theRecorded"/> as recorded.</summary>
    public static int Cases(int theLive, int theRecorded) => IsSampled ? theRecorded : theLive;

    /// <summary>The recorded bytes a loop under <see cref="Budget{T}"/> may take by default (uncompressed).</summary>
    public const long DefaultBudget = 1_500_000;

    /// <summary>
    /// A loop's items, within a budget of recorded bytes (decision 15002): live, all of them; when recording, the items in
    /// turn while the loop's recording stays under <paramref name="theBudget"/>, the rest skipped; when replaying, the
    /// items recorded. With <paramref name="isSpread"/> the items are taken in a spread order (every seventh first, then
    /// the next...), so a corpus's sample reaches across it; with <paramref name="isRollingBack"/> an item whose own
    /// recording passes a quarter of the budget is dropped again (its native calls, replayed, would be skipped too):
    /// only for loops whose items don't depend on each other, nor on a random generator the loop shares.
    /// </summary>
    public static IEnumerable<T> Budget<T>(IEnumerable<T> theItems, long theBudget = DefaultBudget, bool isSpread = false, bool isRollingBack = false)
    {
        if (!IsSampled)
        {
            foreach (T anItem in theItems)
            {
                yield return anItem;
            }
            yield break;
        }
        Session aSession = Current;
        long aStart = aSession.Recorded;
        if (!isSpread)
        {
            // in order, lazily (the items may come from a random generator, or make native calls): stop at the budget
            foreach (T anItem in theItems)
            {
                Session.Mark aMark = IsRecording ? aSession.MarkHere() : default;
                bool isTaken = IsRecording ? aSession.Take(aSession.Recorded - aStart < theBudget) : aSession.Take(null);
                if (!isTaken)
                {
                    yield break;
                }
                yield return anItem;
                if (IsRecording && isRollingBack && aSession.Recorded - aMark.Position > theBudget / 4)
                {
                    aSession.Rollback(aMark);
                    aSession.Take(false);
                    yield break;
                }
            }
            yield break;
        }
        List<T> anItems = [.. theItems];
        foreach (T anItem in anItems.Select((t, i) => (t, i)).OrderBy(p => p.i % 7).ThenBy(p => p.i).Select(p => p.t))
        {
            if (!IsRecording)
            {
                if (aSession.Take(null))
                {
                    yield return anItem;
                }
                continue;
            }
            if (aSession.Recorded - aStart >= theBudget)
            {
                aSession.Take(false);
                continue;
            }
            Session.Mark aMark = aSession.MarkHere();
            aSession.Take(true);
            yield return anItem;
            if (isRollingBack && aSession.Recorded - aMark.Position > theBudget / 4)
            {
                aSession.Rollback(aMark);
                aSession.Take(false);
            }
        }
    }

    /// <summary>A loop of <paramref name="theCount"/> cases (0 to count - 1), in order, within a budget: see <see cref="Budget{T}"/>.</summary>
    public static IEnumerable<int> Budget(int theCount, long theBudget = DefaultBudget) => Budget(Enumerable.Range(0, theCount), theBudget);

    /// <summary>Stands for code only native OCCT can run, in a build without it.</summary>
    public static T NeedsNative<T>() => throw new InvalidOperationException("This needs native OCCT, which this build hasn't (HAS_ORACLE): replay");

    /// <summary>The facade object for a native object, made outside the facade (when recording).</summary>
    public static NativeHandle? Adopt(object? theReal) => theReal is null ? null : Current.Wrap(theReal) as NativeHandle;

    /// <summary>The results' converted forms: an array of facade objects, typed.</summary>
    public static T[] Array<T>(object? theValue) => theValue switch
    {
        null => null!,
        T[] aTyped => aTyped,
        object?[] anArray => [.. anArray.Select(o => (T)o!)],
        _ => throw new InvalidCastException($"Not an array of {typeof(T).Name}: {theValue.GetType().Name}"),
    };

    /// <summary>A recorded enum value as its type.</summary>
    public static T Enum<T>(object? theValue) where T : struct, System.Enum => (T)System.Enum.ToObject(typeof(T), Convert.ToInt64(theValue));

    /// <summary>A constructor's result: the object's number on the tape and the native object (when recording).</summary>
    public readonly record struct Made(int Id, object? Real);

    // ---------------------------------------------------------------------------------------------------------------
    // Files

    /// <summary>The recordings of a test class (test key to tape), from the embedded resource or, when recording, the source tree.</summary>
    private static Dictionary<string, byte[]> Load(string theFile)
        => s_files.GetOrAdd(theFile, f =>
        {
            Stream? aStream = IsRecording
                ? File.Exists(Path.Combine(RecordingsDir, f + ".tape.gz")) ? File.OpenRead(Path.Combine(RecordingsDir, f + ".tape.gz")) : null
                : typeof(Tape).Assembly.GetManifestResourceStream($"Recordings.{f}.tape.gz");
            var aTapes = new Dictionary<string, byte[]>(StringComparer.Ordinal);
            if (aStream is null)
            {
                return aTapes;
            }
            using (aStream)
            {
                using var aGz = new GZipStream(aStream, CompressionMode.Decompress);
                using var aReader = new BinaryReader(aGz, Encoding.UTF8);
                if (aReader.ReadString() != Magic)
                {
                    throw new InvalidDataException($"{f}.tape.gz: not a tape file");
                }
                int aCount = aReader.ReadInt32();
                for (int i = 0; i < aCount; i++)
                {
                    string aKey = aReader.ReadString();
                    aTapes[aKey] = aReader.ReadBytes(aReader.ReadInt32());
                }
            }
            return aTapes;
        });

    private const string Magic = "occtnet-native-tape-1";

    /// <summary>Saves a recorded tape into its class's file in the source tree (replacing the key's earlier one).</summary>
    private static void Save(string theFile, string theKey, byte[] theTape, string? theReplaces)
    {
        lock (s_saveLock)
        {
            Dictionary<string, byte[]> aTapes = Load(theFile);
            if (theReplaces is not null)
            {
                // a test that now names its rows: its single tape goes
                aTapes.Remove(theReplaces);
            }
            aTapes[theKey] = theTape;
            Directory.CreateDirectory(RecordingsDir);
            string aPath = Path.Combine(RecordingsDir, theFile + ".tape.gz");
            using var aStream = File.Create(aPath);
            using var aGz = new GZipStream(aStream, CompressionLevel.Optimal);
            using var aWriter = new BinaryWriter(aGz, Encoding.UTF8);
            aWriter.Write(Magic);
            aWriter.Write(aTapes.Count);
            foreach ((string aKey, byte[] aBytes) in aTapes.OrderBy(p => p.Key, StringComparer.Ordinal))
            {
                aWriter.Write(aKey);
                aWriter.Write(aBytes.Length);
                aWriter.Write(aBytes);
            }
        }
    }

    // ---------------------------------------------------------------------------------------------------------------
    // A test's tape

    internal sealed class Session(string theFile, string theKey, string? theBaseKey = null)
    {
        public string File { get; } = theFile;
        public string Key { get; } = theKey;
        public string BaseKey { get; } = theBaseKey ?? theKey;
        private readonly TapeWriter? myWriter = IsRecording ? new TapeWriter() : null;
        private TapeReader? myReader;
        private readonly Lock myLock = new();
        private int myCalls;
        private int myIds;
        private bool myUsed;
        private int mySuspended;
        private uint myRunning = 2166136261;

        /// <summary>The bytes recorded so far (0 when replaying).</summary>
        public long Recorded => myWriter?.Length ?? 0;

        /// <summary>A budgeted loop's decision for an item: recorded, or (null) read back.</summary>
        public bool Take(bool? theTake)
        {
            lock (myLock)
            {
                myUsed = true;
                if (myWriter is not null)
                {
                    myWriter.String("take");
                    myWriter.Byte(theTake == true ? (byte)1 : (byte)0);
                    return theTake == true;
                }
                string? aStep = Reader.String();
                if (aStep != "take")
                {
                    throw new InvalidOperationException($"{File}.{Key}: a budgeted loop's item, where the recording has {aStep}");
                }
                return Reader.Byte() != 0;
            }
        }

        /// <summary>Where the tape is, to go back to.</summary>
        public readonly record struct Mark(long Position, int Strings, int Ids, uint Running, int Calls);

        public Mark MarkHere()
        {
            lock (myLock)
            {
                return new Mark(myWriter!.Length, myWriter.StringCount, myIds, myRunning, myCalls);
            }
        }

        /// <summary>Drops what was recorded since <paramref name="theMark"/>.</summary>
        public void Rollback(Mark theMark)
        {
            lock (myLock)
            {
                myWriter!.Truncate(theMark.Position, theMark.Strings);
                myIds = theMark.Ids;
                myRunning = theMark.Running;
                myCalls = theMark.Calls;
            }
        }

        /// <summary>The next object's number; 0 while a recorded value is computed (its objects are numbered as it's written).</summary>
        public int NextId() => mySuspended > 0 ? 0 : Interlocked.Increment(ref myIds);

        private TapeReader Reader
        {
            get
            {
                if (myReader is null)
                {
                    if (!Load(File).TryGetValue(Key, out byte[]? aBytes))
                    {
                        throw new InvalidOperationException($"No recording of native OCCT for {File}.{Key}: record it with {RecordVariable}=1 "
                                                            + "(kernel/docs/oracle-testing.md)");
                    }
                    myReader = new TapeReader(aBytes);
                }
                return myReader;
            }
        }

        public void Finish(bool theCheck = true)
        {
            if (myWriter is not null)
            {
                if (myUsed)
                {
                    Save(File, Key, myWriter.ToArray(), Key != BaseKey ? BaseKey : null);
                }
            }
            else if (theCheck && myReader is not null && !myReader.AtEnd)
            {
                throw new InvalidOperationException($"{File}.{Key}: the test made {myCalls} native calls, fewer than recorded");
            }
        }

        public (object?[] Results, object? Real) Call(NativeHandle? theSelf, string theSignature, object?[] theArgs, bool isNew)
        {
            if (mySuspended > 0)
            {
                // inside a recorded value's computation: native runs, untaped
                object?[] aRaw = Recorders.Run(theSignature, theSelf?.Real, theArgs);
                return isNew ? ([], aRaw[0]) : ([.. aRaw.Select(Wrap)], null);
            }
            lock (myLock)
            {
                myUsed = true;
                myCalls++;
                // a running hash of every call's arguments, of which each step keeps a byte: a difference in arguments
                // shows at once, or a few calls later
                myRunning = (myRunning ^ ArgHash(theSelf, theArgs)) * 16777619;
                byte aCheck = (byte)(myRunning ^ (myRunning >> 8) ^ (myRunning >> 16) ^ (myRunning >> 24));
                return myWriter is not null ? Record(theSelf, theSignature, theArgs, isNew, aCheck) : Replay(theSignature, theArgs, aCheck);
            }
        }

        // A step: the member, a header byte (bit 0: it threw; bit 1: it wrote files; the rest: how many results), the
        // arguments' check byte, then the results (tagged values) or the exception, then the files written.

        private (object?[], object?) Replay(string theSignature, object?[] theArgs, byte theCheck)
        {
            TapeReader aReader = Reader;
            if (aReader.AtEnd)
            {
                throw new InvalidOperationException($"{File}.{Key}: native call {myCalls} ({theSignature}) wasn't recorded: the test makes more calls than it did");
            }
            string aRecorded = aReader.String()!;
            byte aHeader = aReader.Byte();
            byte aCheck = aReader.Byte();
            if (aRecorded != theSignature || aCheck != theCheck)
            {
                throw new InvalidOperationException(
                    $"{File}.{Key}: native call {myCalls} is {theSignature}{(aRecorded == theSignature ? " with other arguments (here or a few calls before)" : "")}; "
                    + $"the recording has {aRecorded} here. The port's results feed native's arguments, or the test changed: re-record "
                    + "if native's side changed, or compare differently (phase10-plan.md 3.2)");
            }
            if ((aHeader & 1) != 0)
            {
                throw aReader.Exception();
            }
            var aResults = new object?[aHeader >> 2];
            for (int i = 0; i < aResults.Length; i++)
            {
                aResults[i] = aReader.Value();
            }
            if ((aHeader & 2) != 0)
            {
                int aFiles = aReader.Int();
                for (int i = 0; i < aFiles; i++)
                {
                    int anArg = aReader.Int();
                    byte[] aBytes = (byte[])aReader.Value()!;
                    System.IO.File.WriteAllBytes((string)theArgs[anArg]!, aBytes);
                }
            }
            return (aResults, null);
        }

        private (object?[], object?) Record(NativeHandle? theSelf, string theSignature, object?[] theArgs, bool isNew, byte theCheck)
        {
            TapeWriter aWriter = myWriter!;
            aWriter.String(theSignature);
            // the files the call may write: its rooted path arguments, as they are before it
            var aBefore = new List<(int, DateTime, long)>();
            for (int i = 0; i < theArgs.Length; i++)
            {
                if (theArgs[i] is string aPath && IsPath(aPath))
                {
                    var anInfo = new FileInfo(aPath);
                    aBefore.Add((i, anInfo.Exists ? anInfo.LastWriteTimeUtc : DateTime.MinValue, anInfo.Exists ? anInfo.Length : -1));
                }
            }
            object?[] aRaw;
            try
            {
                aRaw = Recorders.Run(theSignature, theSelf?.Real, theArgs);
            }
            catch (Exception e)
            {
                aWriter.Byte(1);
                aWriter.Byte(theCheck);
                throw aWriter.Exception(e);
            }
            object? aReal = null;
            object?[] aResults;
            if (isNew)
            {
                aReal = aRaw[0];
                aResults = [];
            }
            else
            {
                aResults = [.. aRaw.Select(Wrap)];
            }
            var aWritten = new List<(int, byte[])>();
            foreach ((int anArg, DateTime aTime, long aLength) in aBefore)
            {
                var anInfo = new FileInfo((string)theArgs[anArg]!);
                if (anInfo.Exists && (anInfo.LastWriteTimeUtc != aTime || anInfo.Length != aLength))
                {
                    aWritten.Add((anArg, System.IO.File.ReadAllBytes(anInfo.FullName)));
                }
            }
            if (aResults.Length > 63)
            {
                throw new NotSupportedException($"{theSignature}: {aResults.Length} results");
            }
            aWriter.Byte((byte)((aResults.Length << 2) | (aWritten.Count > 0 ? 2 : 0)));
            aWriter.Byte(theCheck);
            foreach (object? aResult in aResults)
            {
                aWriter.Value(aResult);
            }
            if (aWritten.Count > 0)
            {
                aWriter.Int(aWritten.Count);
                foreach ((int anArg, byte[] aBytes) in aWritten)
                {
                    aWriter.Int(anArg);
                    aWriter.Value(aBytes);
                }
            }
            return (aResults, aReal);
        }

        /// <summary>A native result as the facade's: native objects wrapped, enums as longs, sequences as arrays.</summary>
        public object? Wrap(object? theReal)
        {
            switch (theReal)
            {
                case null:
                case string:
                case bool or int or long or ulong or double or float or byte:
                case byte[] or int[] or long[] or double[] or float[]:
                    return theReal;
                case System.Enum anEnum:
                    return Convert.ToInt64(anEnum);
                case System.Collections.IEnumerable aSequence when theReal is System.Array || theReal.GetType().Namespace != "Build123d.Occt":
                    return aSequence.Cast<object?>().Select(Wrap).ToArray();
                default:
                    for (Type? aType = theReal.GetType(); aType is not null; aType = aType.BaseType)
                    {
                        if (Facade.Create(aType.Name, NextId(), theReal) is NativeHandle aHandle)
                        {
                            return aHandle;
                        }
                    }
                    throw new NotSupportedException($"No facade for a native {theReal.GetType().FullName}");
            }
        }

        /// <summary>A recorded value.</summary>
        public T Value<T>(string theWhat, Func<T> theCompute, Action<TapeWriter, T> theWrite, Func<TapeReader, T> theRead)
        {
            lock (myLock)
            {
                myUsed = true;
                myCalls++;
                if (myWriter is not null)
                {
                    myWriter.String("value " + theWhat);
                }
                else
                {
                    string aRecorded = Reader.String()!;
                    if (aRecorded != "value " + theWhat)
                    {
                        throw new InvalidOperationException($"{File}.{Key}: step {myCalls} is the value {theWhat}; the recording has {aRecorded} here");
                    }
                }
            }
            if (myWriter is not null)
            {
                // computed with the tape suspended: its own native calls aren't taped, as the replay doesn't make them
                T aValue;
                Interlocked.Increment(ref mySuspended);
                try
                {
                    aValue = theCompute();
                }
                finally
                {
                    Interlocked.Decrement(ref mySuspended);
                }
                lock (myLock)
                {
                    myWriter.String("value end " + theWhat);
                    myWriter.Session = this;
                    theWrite(myWriter, aValue);
                }
                return aValue;
            }
            lock (myLock)
            {
                string? anEnd = Reader.String();
                if (anEnd != "value end " + theWhat)
                {
                    throw new InvalidOperationException($"{File}.{Key}: the value {theWhat} isn't where the recording has it ({anEnd})");
                }
                return theRead(Reader);
            }
        }

        /// <summary>
        /// The arguments' hash: numbers to the bit, strings by text, rooted paths by their file's content (temporary names
        /// change from run to run), facade objects by their number on the tape.
        /// </summary>
        private static uint ArgHash(NativeHandle? theSelf, object?[] theArgs)
        {
            var aHash = new Fnv();
            aHash.Add(theSelf?.Id ?? 0);
            foreach (object? anArg in theArgs)
            {
                Add(ref aHash, anArg);
            }
            return aHash.Value;
        }

        private static void Add(ref Fnv theHash, object? theArg)
        {
            switch (theArg)
            {
                case null:
                    theHash.Add(-1L);
                    break;
                case NativeHandle aHandle:
                    theHash.Add(aHandle.Id);
                    break;
                case string aText when IsPath(aText):
                    theHash.Add(System.IO.File.Exists(aText) ? "file " + Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.IO.File.ReadAllBytes(aText)))
                                : Directory.Exists(aText) ? "directory" : "no file");
                    break;
                case string aText:
                    theHash.Add(aText);
                    break;
                case bool b:
                    theHash.Add(b ? 1L : 0L);
                    break;
                case double d:
                    theHash.Add(BitConverter.DoubleToInt64Bits(d));
                    break;
                case float f:
                    theHash.Add(BitConverter.SingleToInt32Bits(f));
                    break;
                case System.Enum e:
                    theHash.Add(Convert.ToInt64(e));
                    break;
                case int or long or ulong or byte or short:
                    theHash.Add(Convert.ToInt64(theArg));
                    break;
                case System.Collections.IEnumerable aSequence:
                    long aCount = 0;
                    foreach (object? anItem in aSequence)
                    {
                        Add(ref theHash, anItem);
                        aCount++;
                    }
                    theHash.Add(aCount);
                    break;
                default:
                    theHash.Add(theArg.ToString() ?? "");
                    break;
            }
        }
    }

    /// <summary>Whether a string argument names a file: rooted, with a separator.</summary>
    private static bool IsPath(string theText)
        => theText.Length > 3 && theText.Length < 400 && theText.IndexOfAny(['\n', '\r']) < 0 && Path.IsPathFullyQualified(theText);

    private struct Fnv()
    {
        public uint Value = 2166136261;

        public void Add(long theValue)
        {
            for (int i = 0; i < 8; i++)
            {
                Value = (Value ^ (byte)(theValue >> (8 * i))) * 16777619;
            }
        }

        public void Add(string theText)
        {
            foreach (char c in theText)
            {
                Value = (Value ^ c) * 16777619;
            }
            Add(theText.Length);
        }
    }
}

/// <summary>
/// The base of the facade's objects: its number on the tape (its identity in arguments) and, when recording, the native
/// wrapper it stands for.
/// </summary>
public abstract class NativeHandle : IDisposable
{
    internal object? Real;

    protected NativeHandle(Tape.Made theMade)
    {
        Id = theMade.Id;
        Real = theMade.Real;
    }

    /// <summary>The object's number on its test's tape.</summary>
    public int Id { get; internal set; }

    public void Dispose()
    {
        (Real as IDisposable)?.Dispose();
        GC.SuppressFinalize(this);
    }
}

/// <summary>An exception native OCCT threw (Build123d.Occt's OcctException), replayed.</summary>
public sealed class OcctException(string theOcctType, string theOcctMessage, string? theOperation, string theMessage) : Exception(theMessage)
{
    /// <summary>As the test raises one itself (Build123d.Occt's constructor).</summary>
    public OcctException(string theOcctType, string theMessage)
        : this(theOcctType, theMessage, null, theMessage.Length > 0 ? $"{theOcctType}: {theMessage}" : theOcctType)
    {
    }

    public string OcctType { get; } = theOcctType;

    public string OcctMessage { get; } = theOcctMessage;

    public string? Operation { get; } = theOperation;

    public bool IsFault => OcctType.StartsWith("OSD_Exception", StringComparison.Ordinal) || OcctType == "unknown";
}

/// <summary>Writes a tape: tagged values, strings pooled.</summary>
public sealed class TapeWriter
{
    private readonly MemoryStream myStream = new();
    private readonly Dictionary<string, int> myStrings = new(StringComparer.Ordinal);

    internal Tape.Session? Session;

    internal byte[] ToArray() => myStream.ToArray();

    internal long Length => myStream.Length;

    internal int StringCount => myStrings.Count;

    /// <summary>Goes back to an earlier length, forgetting the strings pooled since.</summary>
    internal void Truncate(long theLength, int theStrings)
    {
        myStream.SetLength(theLength);
        myStream.Position = theLength;
        foreach (string aText in myStrings.Where(p => p.Value >= theStrings).Select(p => p.Key).ToList())
        {
            myStrings.Remove(aText);
        }
    }

    internal void Byte(byte theValue) => myStream.WriteByte(theValue);

    internal void UInt32(uint theValue)
    {
        Span<byte> aBytes = stackalloc byte[4];
        BitConverter.TryWriteBytes(aBytes, theValue);
        myStream.Write(aBytes);
    }

    public void Int(long theValue)
    {
        // zigzag varint
        ulong aValue = (ulong)((theValue << 1) ^ (theValue >> 63));
        while (aValue >= 0x80)
        {
            myStream.WriteByte((byte)(aValue | 0x80));
            aValue >>= 7;
        }
        myStream.WriteByte((byte)aValue);
    }

    public void String(string? theText)
    {
        if (theText is null)
        {
            Int(0);
        }
        else if (myStrings.TryGetValue(theText, out int anIndex))
        {
            Int(anIndex + 2);
        }
        else
        {
            Int(1);
            byte[] aBytes = Encoding.UTF8.GetBytes(theText);
            Int(aBytes.Length);
            myStream.Write(aBytes);
            myStrings[theText] = myStrings.Count;
        }
    }

    private void Raw<T>(T[] theValues) where T : unmanaged
    {
        Int(theValues.Length);
        myStream.Write(System.Runtime.InteropServices.MemoryMarshal.AsBytes(theValues.AsSpan()));
    }

    /// <summary>A tagged value: null, a number, a string, an array, or a facade object (its type).</summary>
    public void Value(object? theValue)
    {
        switch (theValue)
        {
            case null: Byte(0); break;
            case bool b: Byte(1); Byte(b ? (byte)1 : (byte)0); break;
            case int i: Byte(2); Int(i); break;
            case long l: Byte(3); Int(l); break;
            case ulong u: Byte(4); Raw([u]); break;
            case double d: Byte(5); Raw([d]); break;
            case float f: Byte(6); Raw([f]); break;
            case string s: Byte(7); String(s); break;
            case NativeHandle h:
                Byte(8);
                String(h.GetType().Name);
                if (h.Id == 0)
                {
                    // made inside a recorded value: numbered now, as the replay numbers it when it reads it
                    h.Id = Session!.NextId();
                }
                break;
            case byte[] a: Byte(9); Raw(a); break;
            case int[] a: Byte(10); Raw(a); break;
            case long[] a: Byte(11); Raw(a); break;
            case double[] a: Byte(12); Raw(a); break;
            case float[] a: Byte(13); Raw(a); break;
            case object?[] a:
                Byte(14);
                Int(a.Length);
                foreach (object? anItem in a)
                {
                    Value(anItem);
                }
                break;
            case byte b: Byte(15); Byte(b); break;
            default: throw new NotSupportedException($"A tape can't hold a {theValue.GetType().FullName}");
        }
    }

    /// <summary>A facade object (or null), which the replay makes again with the same type.</summary>
    public void Object(object? theObject) => Value((NativeHandle?)theObject);

    /// <summary>An exception: recorded, and returned as the facade's to throw.</summary>
    internal Exception Exception(Exception theException)
    {
        Exception anInner = theException is TargetInvocationException { InnerException: { } e } ? e : theException;
        string aType = anInner.GetType().FullName!;
        String(aType);
        String(anInner.Message);
        (string anOcctType, string anOcctMessage, string? anOperation) = Recorders.OcctError(anInner);
        String(anOcctType);
        String(anOcctMessage);
        String(anOperation);
        return TapeReader.Make(aType, anInner.Message, anOcctType, anOcctMessage, anOperation);
    }
}

/// <summary>Reads a tape.</summary>
public sealed class TapeReader(byte[] theBytes)
{
    private int myPos;
    private readonly List<string> myStrings = [];

    internal bool AtEnd => myPos >= theBytes.Length;

    internal byte Byte() => theBytes[myPos++];

    internal uint UInt32()
    {
        uint aValue = BitConverter.ToUInt32(theBytes, myPos);
        myPos += 4;
        return aValue;
    }

    public long Long()
    {
        ulong aValue = 0;
        for (int aShift = 0; ; aShift += 7)
        {
            byte b = theBytes[myPos++];
            aValue |= (ulong)(b & 0x7F) << aShift;
            if (b < 0x80)
            {
                break;
            }
        }
        return (long)(aValue >> 1) ^ -(long)(aValue & 1);
    }

    public int Int() => (int)Long();

    public string? String()
    {
        int aTag = Int();
        if (aTag == 0)
        {
            return null;
        }
        if (aTag >= 2)
        {
            return myStrings[aTag - 2];
        }
        int aLength = Int();
        string aText = Encoding.UTF8.GetString(theBytes, myPos, aLength);
        myPos += aLength;
        myStrings.Add(aText);
        return aText;
    }

    private T[] Raw<T>() where T : unmanaged
    {
        int aCount = Int();
        var aValues = new T[aCount];
        int aBytes = aCount * System.Runtime.CompilerServices.Unsafe.SizeOf<T>();
        theBytes.AsSpan(myPos, aBytes).CopyTo(System.Runtime.InteropServices.MemoryMarshal.AsBytes(aValues.AsSpan()));
        myPos += aBytes;
        return aValues;
    }

    public object? Value()
    {
        byte aTag = Byte();
        return aTag switch
        {
            0 => null,
            1 => Byte() != 0,
            2 => Int(),
            3 => Long(),
            4 => Raw<ulong>()[0],
            5 => Raw<double>()[0],
            6 => Raw<float>()[0],
            7 => String(),
            8 => Facade.Create(String()!, Tape.Current.NextId(), null),
            9 => Raw<byte>(),
            10 => Raw<int>(),
            11 => Raw<long>(),
            12 => Raw<double>(),
            13 => Raw<float>(),
            14 => Enumerable.Range(0, Int()).Select(_ => Value()).ToArray(),
            15 => Byte(),
            _ => throw new InvalidDataException($"A bad tag {aTag} on the tape"),
        };
    }

    /// <summary>A facade object (or null) written by <see cref="TapeWriter.Object"/>.</summary>
    public T? Object<T>() where T : class => (T?)Value();

    internal Exception Exception()
    {
        string aType = String()!;
        string aMessage = String()!;
        string anOcctType = String()!;
        string anOcctMessage = String()!;
        string? anOperation = String();
        return Make(aType, aMessage, anOcctType, anOcctMessage, anOperation);
    }

    internal static Exception Make(string theType, string theMessage, string theOcctType, string theOcctMessage, string? theOperation)
    {
        if (theType == "Build123d.Occt.OcctException")
        {
            return new OcctException(theOcctType, theOcctMessage, theOperation, theMessage);
        }
        Type? aType = typeof(object).Assembly.GetType(theType);
        if (aType is not null && typeof(Exception).IsAssignableFrom(aType)
            && aType.GetConstructor([typeof(string)]) is { } aCtor)
        {
            return (Exception)aCtor.Invoke([theMessage]);
        }
        return new InvalidOperationException($"{theType}: {theMessage}");
    }
}

/// <summary>Starts and ends each test's tape (<see cref="Tape"/>).</summary>
[AttributeUsage(AttributeTargets.Assembly | AttributeTargets.Class | AttributeTargets.Method)]
public sealed class NativeTapeAttribute : BeforeAfterTestAttribute
{
    public override void Before(MethodInfo methodUnderTest) => Tape.Begin(methodUnderTest);

    public override void After(MethodInfo methodUnderTest) => Tape.End(true);
}

/// <summary>Native OCCT's side of each facade member, when recording (<c>Native.Record.g.cs</c>).</summary>
internal static partial class Recorders
{
    private static readonly Dictionary<string, Func<object?, object?[], object?[]>> s_recorders = new(StringComparer.Ordinal);

    static partial void Register(Dictionary<string, Func<object?, object?[], object?[]>> r);

    static partial void Error(Exception theException, ref (string, string, string?) theError);

    static Recorders() => Register(s_recorders);

    public static object?[] Run(string theSignature, object? theSelf, object?[] theArgs)
    {
        if (!s_recorders.TryGetValue(theSignature, out var aRecorder))
        {
            throw new InvalidOperationException($"Recording needs native OCCT (HAS_ORACLE), which can run {theSignature}: build with Build123dNativeRoot");
        }
        return aRecorder(theSelf, theArgs);
    }

    public static (string, string, string?) OcctError(Exception theException)
    {
        (string, string, string?) anError = ("", "", null);
        Error(theException, ref anError);
        return anError;
    }
}
